  "dsh": {
    "profile": {
      "bundles": [
        "@deepseek-ai/dsh-base",
        "@deepseek-ai/dsh-web-app",
        // 新增：追加到层列表末尾
        "dsh-plugin-marketplace"
      ]
    }
  }
}
